package com.hospital.smartqueue.department.api;
import com.hospital.smartqueue.department.application.DepartmentService; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/hospitals/{hospitalId}/branches/{branchId}/departments") public class DepartmentController { private final DepartmentService service; public DepartmentController(DepartmentService s){service=s;} public record Request(@NotBlank String name){} public record Response(UUID id,UUID branchId,String name){} @PostMapping public ResponseEntity<Response> create(@PathVariable UUID hospitalId,@PathVariable UUID branchId,@Valid @RequestBody Request r){var d=service.create(hospitalId,branchId,r.name());return ResponseEntity.status(HttpStatus.CREATED).body(new Response(d.getId(),d.getBranchId(),d.getName()));} @GetMapping public List<Response> list(@PathVariable UUID hospitalId,@PathVariable UUID branchId){return service.list(hospitalId,branchId).stream().map(d->new Response(d.getId(),d.getBranchId(),d.getName())).toList();}}
